function exactFlags(readings, k) {
  let total = 0;
  for (let start = 0; start < readings.length; start++) {
    let flagged = 0;
    for (let end = start; end < readings.length; end++) {
      if (Math.abs(readings[end]) % 2 === 1) flagged++;
      if (flagged === k) total++;
    }
  }
  return total;
}

function exactFlags(readings, k) {
  const seen = new Array(readings.length + 1).fill(0);
  seen[0] = 1;
  let flagged = 0;
  let total = 0;
  for (const reading of readings) {
    if (Math.abs(reading) % 2 === 1) flagged++;
    if (flagged >= k) total += seen[flagged - k];
    seen[flagged]++;
  }
  return total;
}

function exactFlags(readings, k) {
  const atMost = (limit) => {
    if (limit < 0) return 0;
    let left = 0;
    let flagged = 0;
    let stretches = 0;
    for (let right = 0; right < readings.length; right++) {
      if (Math.abs(readings[right]) % 2 === 1) flagged++;
      while (flagged > limit) {
        if (Math.abs(readings[left]) % 2 === 1) flagged--;
        left++;
      }
      stretches += right - left + 1;
    }
    return stretches;
  };
  return atMost(k) - atMost(k - 1);
}
